impl CapabilityClient for SupportSlaClient {
    type Dependencies = PluginDependencies;
    type Error = RuntimeFailure;

    const CAPABILITY_ID: &'static str = CAPABILITY_ID;
    const DESCRIPTOR_VERSION: &'static str = DESCRIPTOR_VERSION;

    fn from_dependencies(dependencies: &PluginDependencies) -> Result<Self, RuntimeFailure> {
        Ok(Self {
            archive_policy: dependencies.one::<SupportSlaArchivePolicy>()?,
            create_policy: dependencies.one::<SupportSlaCreatePolicy>()?,
            get_clock: dependencies.one::<SupportSlaGetClock>()?,
            get_policy: dependencies.one::<SupportSlaGetPolicy>()?,
            list_breaches: dependencies.one::<SupportSlaListBreaches>()?,
            list_clocks: dependencies.one::<SupportSlaListClocks>()?,
            list_policies: dependencies.one::<SupportSlaListPolicies>()?,
            observe_case_message: dependencies.one::<SupportSlaObserveCaseMessage>()?,
            observe_case_snapshot: dependencies.one::<SupportSlaObserveCaseSnapshot>()?,
            reconcile: dependencies.one::<SupportSlaReconcile>()?,
            update_policy: dependencies.one::<SupportSlaUpdatePolicy>()?,
        })
    }

    fn already_connected() -> RuntimeFailure {
        RuntimeFailure::PluginFailure {
            detail: format!("Capability Port {CAPABILITY_ID} was connected more than once"),
        }
    }
}

impl CapabilityClientMany for SupportSlaClient {
    fn many_from_dependencies(
        dependencies: &PluginDependencies,
    ) -> Result<Vec<BoundCapabilityClient<Self>>, RuntimeFailure> {
        dependencies
            .bindings()
            .iter()
            .filter(|binding| binding.capability_id() == CAPABILITY_ID)
            .map(|binding| {
                Ok(BoundCapabilityClient::new(
                    binding.provider_instance(),
                    Self {
                    archive_policy: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<SupportSlaArchivePolicy>()?,
                    create_policy: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<SupportSlaCreatePolicy>()?,
                    get_clock: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<SupportSlaGetClock>()?,
                    get_policy: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<SupportSlaGetPolicy>()?,
                    list_breaches: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<SupportSlaListBreaches>()?,
                    list_clocks: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<SupportSlaListClocks>()?,
                    list_policies: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<SupportSlaListPolicies>()?,
                    observe_case_message: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<SupportSlaObserveCaseMessage>()?,
                    observe_case_snapshot: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<SupportSlaObserveCaseSnapshot>()?,
                    reconcile: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<SupportSlaReconcile>()?,
                    update_policy: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<SupportSlaUpdatePolicy>()?,
                    },
                ))
            })
            .collect()
    }
}

